insert into public.email_automations(id,key,name,trigger_type,is_active) values('4b493ec4-2624-543b-891b-d5068faefd89','course_month-holiness','Месяц святости','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-holiness','Месяц святости','practicum','',90,3,5,'4b493ec4-2624-543b-891b-d5068faefd89','e2d1870bd355f2fcc7e0353f2b2e7a6a8ed6cff61f376b9ca137811fa2172c77') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('a9cb4a45-5762-5ce9-8eb8-5bedb43ab6b7','4b493ec4-2624-543b-891b-d5068faefd89','Урок 1',1,0,'{Месяц святости} Добро пожаловать!','{"ru":"{Месяц святости} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие результатов<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь светом, ощущением святости и связи с Высшим... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите на первом уроке. И каждое своё действие совершайте с пониманием, что это ваша практика для гармонизации седьмой чакры.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. На этом уроке мы наметим цели и поведенческие практики для каждого участника практикума (ведь для каждого они свои). Очень важно чтобы, планируя месяц движения вперёд, у вас было правильное понимание того внутреннего намерения, которое привело вас на этот практикум. Этот урок посвящен тому, чтобы вы глубже разобрались в том, что такое седьмая чакра, почувствовали её энергию, свои ограничения, а также сформулировали лично для себя намерение на этот месяц и наметили связанные с ним практики на каждый день. Длительность урока - 1.3 часа. Рекомендую вам не разбивать урок на части, а пройти его на одном дыхании. Как раз, когда возникает усталость, ощущение перегруза, теряется нить или интерес, и хочется прерваться, рефлексируйте эти моменты, оставаясь в практике.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!</p><p></p><p>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие результатов<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь светом, ощущением святости и связи с Высшим... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите на первом уроке. И каждое своё действие совершайте с пониманием, что это ваша практика для гармонизации седьмой чакры.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. На этом уроке мы наметим цели и поведенческие практики для каждого участника практикума (ведь для каждого они свои). Очень важно чтобы, планируя месяц движения вперёд, у вас было правильное понимание того внутреннего намерения, которое привело вас на этот практикум. Этот урок посвящен тому, чтобы вы глубже разобрались в том, что такое седьмая чакра, почувствовали её энергию, свои ограничения, а также сформулировали лично для себя намерение на этот месяц и наметили связанные с ним практики на каждый день. Длительность урока - 1.3 часа. Рекомендую вам не разбивать урок на части, а пройти его на одном дыхании. Как раз, когда возникает усталость, ощущение перегруза, теряется нить или интерес, и хочется прерваться, рефлексируйте эти моменты, оставаясь в практике.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!</p><p></p><p>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-01-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие результатов<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь светом, ощущением святости и связи с Высшим... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите на первом уроке. И каждое своё действие совершайте с пониманием, что это ваша практика для гармонизации седьмой чакры.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. На этом уроке мы наметим цели и поведенческие практики для каждого участника практикума (ведь для каждого они свои). Очень важно чтобы, планируя месяц движения вперёд, у вас было правильное понимание того внутреннего намерения, которое привело вас на этот практикум. Этот урок посвящен тому, чтобы вы глубже разобрались в том, что такое седьмая чакра, почувствовали её энергию, свои ограничения, а также сформулировали лично для себя намерение на этот месяц и наметили связанные с ним практики на каждый день. Длительность урока - 1.3 часа. Рекомендую вам не разбивать урок на части, а пройти его на одном дыхании. Как раз, когда возникает усталость, ощущение перегруза, теряется нить или интерес, и хочется прерваться, рефлексируйте эти моменты, оставаясь в практике.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!</p><p></p><p>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-01','month-holiness',1,0,'Урок 1','[{"type":"video","vimeoId":"1102475649"},{"type":"text","markdown":"ЗАДАНИЕ:\nСформулируйте своё намерение на этот месяц практик, а также определите действия (практики), которые вы будете выполнять ежедневно, несмотря ни на какие непредвиденные затруднения."}]'::jsonb,'a9cb4a45-5762-5ce9-8eb8-5bedb43ab6b7') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('678e59e7-6875-5fb5-b705-552f0acad4a8','4b493ec4-2624-543b-891b-d5068faefd89','Урок 2',2,0,'{Месяц святости} Урок 2','{"ru":"{Месяц святости} Урок 2"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. Сегодня мы сделаем следующий шаг - выполним асаны в этом потоке. Длительность урока - 2 часа. Рекомендую не разбивать занятие на части, а пройти всё на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!</p><p></p><p>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. Сегодня мы сделаем следующий шаг - выполним асаны в этом потоке. Длительность урока - 2 часа. Рекомендую не разбивать занятие на части, а пройти всё на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!</p><p></p><p>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. Сегодня мы сделаем следующий шаг - выполним асаны в этом потоке. Длительность урока - 2 часа. Рекомендую не разбивать занятие на части, а пройти всё на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!</p><p></p><p>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-02','month-holiness',2,2,'Урок 2','[{"type":"video","vimeoId":"1102475813"},{"type":"text","markdown":"ЗАДАНИЕ:\nЕжедневно действовуйте, как определили для себя на первом занятии, а также выполняйте суставную гимнастику и несложные асаны в потоке седьмой чакры."}]'::jsonb,'678e59e7-6875-5fb5-b705-552f0acad4a8') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('65d7df5b-db13-5433-b399-2b3064abccf0','4b493ec4-2624-543b-891b-d5068faefd89','Урок 3',3,0,'{Месяц святости} Урок 3','{"ru":"{Месяц святости} Урок 3"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-03','month-holiness',3,7,'Урок 3','[{"type":"video","vimeoId":"1105020930"},{"type":"text","markdown":"ЗАДАНИЕ:\nСохраняйте осознанность к энергиям седьмой чакры и выполняйте те практики, которые соответствуют вашему намерению."}]'::jsonb,'65d7df5b-db13-5433-b399-2b3064abccf0') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('5a095cb3-1c0b-57e6-b06a-16d4ed722e73','4b493ec4-2624-543b-891b-d5068faefd89','Дополнительная практика',4,0,'{Месяц святости} Дополнительная практика','{"ru":"{Месяц святости} Дополнительная практика"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-04','month-holiness',4,3,'Дополнительная практика','[{"type":"video","vimeoId":"1141367686","practiceId":"c3f1acc2-6929-408f-a73c-f13f80084716"}]'::jsonb,'5a095cb3-1c0b-57e6-b06a-16d4ed722e73') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2d7cb280-d7c1-545e-8b15-ba3264929461','4b493ec4-2624-543b-891b-d5068faefd89','Урок 4',5,0,'{Месяц святости} Урок 4','{"ru":"{Месяц святости} Урок 4"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке „День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке „День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке „День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-05','month-holiness',5,4,'Урок 4','[{"type":"video","vimeoId":"1105020970"},{"type":"text","markdown":"ЗАДАНИЕ:\nСформулируйте своё намерение на этот месяц практик, а также определите действия (практики), которые вы будете выполнять ежедневно, несмотря ни на какие непредвиденные затруднения."}]'::jsonb,'2d7cb280-d7c1-545e-8b15-ba3264929461') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('4d843a2a-5915-55dd-8993-f2025c8d55b0','4b493ec4-2624-543b-891b-d5068faefd89','Ещё одна дополнительная практика',6,0,'{Месяц святости} Ещё одна дополнительная практика','{"ru":"{Месяц святости} Ещё одна дополнительная практика"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-06','month-holiness',6,3,'Ещё одна дополнительная практика','[{"type":"video","vimeoId":"1151148075","practiceId":"70d48e64-66c0-4eae-b077-107cefba0dcb"}]'::jsonb,'4d843a2a-5915-55dd-8993-f2025c8d55b0') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2c19d6e9-be1a-5035-9af5-8d02e4a8a31b','4b493ec4-2624-543b-891b-d5068faefd89','Урок 5',7,0,'{Месяц святости} Урок 5','{"ru":"{Месяц святости} Урок 5"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе - на вкладке „День“.</p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href="https://zamkovoi.yoga/mmz/">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе - на вкладке „День“.</p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе - на вкладке „День“.</p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-holiness-07','month-holiness',7,4,'Урок 5','[{"type":"video","vimeoId":"1105021017"},{"type":"text","markdown":"####Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты. И теперь предлагаю вам не терять волну, и глубже поработать с 7 чакрой, чтобы получить ещё более интересные результаты.\n- Интенсив по 7 чакре: https://zamkovoi.yoga/i7/\n- Курс \"Путь души\": https://zamkovoi.yoga/yogas/\n\nИли - интересная альтернатива - сприглашаю вас на практикум, посвященный мужско-женском проявлениям. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - https://zamkovoi.yoga/mmz/"}]'::jsonb,'2c19d6e9-be1a-5035-9af5-8d02e4a8a31b') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('0fe9f9c2-5bb0-52ba-9f6e-2588e75ae4d7','4b493ec4-2624-543b-891b-d5068faefd89','Завершение практикума',8,0,'{Месяц святости} Завершение практикума','{"ru":"{Месяц святости} Завершение практикума"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Если вы ещё не записались на практики месяца &quot;М+Ж&quot;, то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме &quot;Месяц любви&quot;, а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href="https://zamkovoi.yoga/mmz/">https://zamkovoi.yoga/mmz/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href="https://zamkovoi.yoga/i7/">https://zamkovoi.yoga/i7/</a><br>- Курс &quot;Путь души&quot;: <a href="https://zamkovoi.yoga/yogas/">https://zamkovoi.yoga/yogas/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png\" alt=\"Месяц святости\" width=\"504\" height=\"159\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Если вы ещё не записались на практики месяца &quot;М+Ж&quot;, то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме &quot;Месяц любви&quot;, а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href=\"https://zamkovoi.yoga/i7/\">https://zamkovoi.yoga/i7/</a><br>- Курс &quot;Путь души&quot;: <a href=\"https://zamkovoi.yoga/yogas/\">https://zamkovoi.yoga/yogas/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-completion-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы почувствовали и улучшили состояние связи с Богом. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>И, так как месяц святости закончился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я мог давать вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Если вы ещё не записались на практики месяца &quot;М+Ж&quot;, то я приглашаю вас сделать это прямо сейчас! Вас ожидает интереснейшая программа. Мы направим внимание на любовь. Но не в том глобальном космическом виде, с которым мы взаимодействовали в практикуме &quot;Месяц любви&quot;, а именно в её мужско-женском проявлении. Тема актуальна практически для каждого, независимо от семейного статуса и возраста. Кому-то нужно гармонизировать настоящее, кому-то прошлое, кому-то и то и другое :) Чтобы ознакомиться с описанием этой программы и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие седьмой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив по 7 чакре: <a href=\"https://zamkovoi.yoga/i7/\">https://zamkovoi.yoga/i7/</a><br>- Курс &quot;Путь души&quot;: <a href=\"https://zamkovoi.yoga/yogas/\">https://zamkovoi.yoga/yogas/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
